sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
	var userId = g_form.getValue('u_user_patient');
	// g_form.addInfoMessage('user id : ' + userId);
	var myScript = new GlideAjax('global.PatientUtilsClient');
	myScript.addParam('sysparm_name', 'fetchPatientDetails');
	myScript.addParam('sysparm_user_id', userId);
	myScript.getXMLAnswer(getResponse);

	function getResponse(result){
		var _res = JSON.parse(result);
		g_form.setValue('u_first_name', _res.first_name);
		g_form.setValue('u_last_name', _res.last_name);
		g_form.setValue('u_email', _res.email);
		g_form.setValue('u_contact_number', _res.mobile);
	}


}
